function secret(){const s=process.env.SESSION_SECRET;if(s)return s;if(process.env.NODE_ENV!=='production')return 'local-dev-session-secret-change-before-deploy';throw new Error('SESSION_SECRET is required.');}
function encodeSession(v:Session){const body=Buffer.from(JSON.stringify(v)).toString('base64url');return body+'.'+createHmac('sha256',secret()).update(body).digest('base64url');}
function decodeCookie(raw?:string):Session|null{if(!raw)return null;const [body,sig]=raw.split('.');if(!body||!sig)return null;const expected=createHmac('sha256',secret()).update(body).digest();let actual:Buffer;try{actual=Buffer.from(sig,'base64url')}catch{return null}if(expected.length!==actual.length||!timingSafeEqual(expected,actual))return null;try{const s=JSON.parse(Buffer.from(body,'base64url').toString()) as Session;return s.exp>Date.now()?s:null}catch{return null}}
function readSession(req:NextRequest):Session|null{const playerView=req.nextUrl.searchParams.get('view')==='player'||req.headers.get('x-everlight-portal')==='player';return playerView?decodeCookie(req.cookies.get(PLAYER_COOKIE)?.value):decodeCookie(req.cookies.get(DM_COOKIE)?.value)}
