function playerView(s:CampaignState,id:PlayerId){const p=s.players[id];return {sessionRecap:s.sessionRecap,player:{...p,clues:s.deliveredClues[id]??[]},day:s.day,flames:s.flames.map(n=>flames.find(f=>f.name===n)).filter(Boolean),mapUnlocked:s.mapUnlocked,missions:s.missions.filter(m=>m.day<=s.day),familyPlans,completedPlanIds:s.completedPlanIds,dmMode:s.dmMode,checkpoint:s.checkpoint,storyProgress:s.storyProgress,lastCheck:s.lastCheck,narration:s.narration,recapHistory:s.recapHistory??[],artKey:sceneArtPlan(s,id).key,storyChoices:s.storyChoices?.[String(s.day)+'-'+String(s.checkpoint)]??{},enemies:s.enemies,combatPhase:s.combatPhase??(s.combat?'active':'inactive'),battleNote:s.battleNote??'',teamworkBonus:s.teamworkBonuses?.[id]??0,party:Object.values(s.players).map(({id,name,character,className,joined,hp,maxHp,defense})=>({id,name,character,className,joined,hp,maxHp,defense}))}}
