const storyEncounters:Partial<Record<number,{name:string;count:number;hp:number;defense:number;attack:number;damage:string;approach:string}>>={1:{name:'Dust Goblin',count:2,hp:5,defense:10,attack:2,damage:'1d4',approach:'Helping with the cleanup or speaking kindly can end this encounter without a fight.'},2:{name:'Shadow Moth',count:2,hp:6,defense:11,attack:2,damage:'1d4',approach:'Bright light weakens their next attack; solving the lantern puzzle can disperse them.'},3:{name:'Ornament Mimic',count:2,hp:7,defense:11,attack:2,damage:'1d4+1',approach:'An apology, repair offer, or handmade ornament can make peace.'},4:{name:'Hollow King',count:1,hp:20,defense:12,attack:3,damage:'1d6',approach:'A sincere invitation ends the battle; each restored flame may remove 4 HP or cancel an attack.'}};
async function sceneArt(req: NextRequest, session: Session, state: CampaignState) {
  const playerId = session.playerId;
  const { day, checkpoint } = state;
  const query = req.nextUrl.searchParams;
  if (session.kind !== 'player' || !playerId || !Object.hasOwn(heroSpeakers, playerId) ||
      query.get('day') !== String(day) || query.get('checkpoint') !== String(checkpoint) ||
      !hasSharedStory(day, checkpoint)) {
    return new Response(null, { status: 404 });
  }

  const { key, fallbackKey, bundled, previous } = sceneArtPlan(state, playerId);
  const local = localEnabled();
  const db = local ? null : createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, {
      auth: { persistSession: false },
    },
  );

  async function load(fileKey: string, useBundled = false) {
    if (useBundled || local) {
      const file = useBundled
        ? path.join(process.cwd(), 'assets', 'scene-art', playerId + '.webp')
        : path.join(process.cwd(), '.everlight-art', fileKey);
      try {
        return new Uint8Array(await readFile(file));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    }
    const result = await db?.storage.from('everlight-scene-art').download(fileKey);
    return result?.data ?? null;
  }

  const generated = await load(generatedSceneArtKey(state));
  if (generated) return new Response(generated, {
    headers: { 'Content-Type': 'image/webp', 'Cache-Control': 'private, no-store', 'X-Everlight-Art': 'generated' },
  });
  const image = await load(key, bundled && !previous);
  const fallback = !image && previous ? await load(fallbackKey, bundled) : null;
  return image || fallback ? new Response(image ?? fallback, {
    headers: {
      'Content-Type': 'image/webp',
      'Cache-Control': 'private, no-store',
      'X-Everlight-Art': fallback ? 'fallback' : previous ? 'action' : 'scene',
    },
  }) : new Response(null, { status: 404 });
}

export async function GET(req:NextRequest){try{const session=readSession(req);if(!session)return NextResponse.json({error:'Sign in or join with your invitation.'},{status:401});const s=await getState();if(req.nextUrl.searchParams.has('art'))return await sceneArt(req,session,s);return NextResponse.json(session.kind==='dm'?{state:s,days,flames,familyPlans}:{player:playerView(s,session.playerId!)});}catch(e){return NextResponse.json({error:e instanceof Error?e.message:'Unable to load game.'},{status:500})}}
